import sys

MOD = 998244353

def invs(n, p):
    res = [0] * n
    res[1] = 1
    for i in range(2, n):
        res[i] = (p - (p // i) * res[p % i] % p) % p
    return res

def main():
    input_line = sys.stdin.readline().strip()
    n, k, l = map(int, input_line.split())

    invs_list = invs(2 * n + 3, MOD)
    dp = [[0] * (n + 1) for _ in range(2 * n + 1)]
    dp[0][1] = 1

    for i in range(1, 2 * n):
        maxPrev = min(2 * n - i, i)
        maxCurr = min(2 * n - i - 1, i + 1)
        for j in range(maxPrev + 1):
            if dp[i - 1][j] != 0:
                if j > 0:
                    dp[i][j - 1] = (dp[i][j - 1] + dp[i - 1][j] * j % MOD * invs_list[2 * n - i]) % MOD
                if j < maxCurr:
                    dp[i][j + 1] = (dp[i][j + 1] + dp[i - 1][j] * (2 * n - i - j) % MOD * invs_list[2 * n - i]) % MOD

    answer = 0
    for i in range(2 * n):
        for j in range(k, n + 1):
            answer = (answer + dp[i][j]) % MOD
    answer = answer * l % MOD * invs_list[2 * n + 1] % MOD
    print(answer)

if __name__ == "__main__":
    main()

